INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000001', 'passport-renewal-rawalpindi', 'Passport Renewal in Rawalpindi', 'پاسپورٹ کی تجدید — راولپنڈی', 'Step-by-step guide to renewing your 36-page Pakistani e-Passport at Regional Passport Office, GT Road, Rawalpindi (or online via DGIP portal). Pakistan issues only e-passports since Oct 2026 — MRP is discontinued.', 'Passport', 'Rawalpindi', 9000, 15000, 22500, 'Pakistan now issues only e-passports since Oct 2026; MRP is discontinued. For a 36-page e-passport: 5 years is Rs. 9,000 Normal and Rs. 15,000 Urgent; 10 years is Rs. 13,500 Normal and Rs. 22,500 Urgent.', 'Normal: 21 working days | Urgent: 5 working days | Executive: 2 working days at Executive Offices', 'Regional Passport Office, Rawalpindi (GT Road)', 'Regional Passport Office, GT Road, Rawalpindi. Also available online via DGIP portal.', 'Mon–Thu: 8:30 AM – 2:00 PM | Fri: 8:30 AM – 12:30 PM (DGIP Online Portal 24/7)', 'Tuesday to Thursday, 8:30 AM to 10:00 AM (Monday is the most crowded day)', 'https://dgip.gov.pk/', '2026-11-17T00:00:00Z', TRUE, FALSE, 1) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000002', 'cnic-renewal-rawalpindi', 'CNIC Renewal in Rawalpindi', 'شناختی کارڈ کی تجدید — راولپنڈی', 'Complete official guide to renewing your Smart CNIC (SNIC) or Ordinary CNIC at NADRA Mega Center, Saddar, Rawalpindi or via the official PakID app — with verified NADRA fees, delivery days, and Rule 12 requirements.', 'Identity', 'Rawalpindi', 750, 1500, 2500, 'Official NADRA renewal fees (nadra.gov.pk/feeStructure): Smart CNIC (SNIC) is Rs. 750 Normal (31 days), Rs. 1,500 Urgent (23 days), and Rs. 2,500 Executive (9 days). Ordinary CNIC (Teslin) is Rs. 400 Normal (15 days), Rs. 1,150 Urgent (12 days), and Rs. 2,150 Executive (6 days). No attestation is required for renewal. 24/7 NADRA Helpline: 1777 (mobile) or +92 51 111 786 100.', '45 mins–1.5 hrs at Mega Center (2+ hrs Sat) | Smart: 31/23/9 days | Ordinary: 15/12/6 days', 'NADRA Mega Center, Murree Road (Rehmanabad) / Saddar & Cantt, Rawalpindi', 'Mega Center: Millennium Mall, 62-A, Rehmanabad, Murree Road, Rawalpindi (3 shifts, open Saturday). Also CSD Lalkurti / Saddar Rawalpindi Cantt (2 shifts) & CFC Kachehri Chowk, or PakID mobile app. 24/7 Helpline: 1777 / +92 51 111 786 100.', 'Mega Center Murree Rd: 3 Shifts (Mon–Sat) | Cantt / Saddar: 2 Shifts (Mon–Sat) | PakID 24/7', 'Weekday 9:00 AM to 11:00 AM (avoid Saturday — 2+ hours wait)', 'https://www.nadra.gov.pk/feeStructure', '2026-11-17T00:00:00Z', TRUE, FALSE, 2) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000003', 'driving-licence-renewal-rawalpindi', 'Driving Licence Renewal in Rawalpindi', 'ڈرائیونگ لائسنس کی تجدید — راولپنڈی', 'How to renew your Punjab motorcycle, car/jeep, or LTV/HTV driving licence at Police Khidmat Markaz Rawalpindi or online via Dastak Punjab and DLIMS with home courier delivery.', 'Driving', 'Rawalpindi', 1830, 930, 2330, 'Punjab 1-year renewal + Rs. 480 courier fee: Motorcycle Rs. 450 (Rs. 930 with courier), Car/Jeep Rs. 1,350 (Rs. 1,830 with courier), LTV/HTV Rs. 1,850 (Rs. 2,330 with courier). Late fine for car: Rs. 675 (1–3 months late) and Rs. 1,350 (3–6 months late).', '20–30 mins at center | 10 mins online | Courier delivery: 7–10 days', 'Police Khidmat Markaz, Rawalpindi', 'Police Khidmat Markaz, Rawalpindi. Also available online via Dastak Punjab and DLIMS.', 'Mon–Sat: 9:00 AM – 5:00 PM (Dastak Punjab & DLIMS online 24/7)', 'Weekday 9:00 AM to 11:00 AM (avoid Saturday)', 'https://dlims.punjab.gov.pk/', '2026-11-17T00:00:00Z', TRUE, FALSE, 3) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000004', 'fbr-ntn-for-freelancers', 'FBR NTN Registration for Freelancers', 'فری لانسرز کے لیے ایف بی آر این ٹی این', '100% free official guide to registering as an individual taxpayer on FBR IRIS (iris.fbr.gov.pk) via Form 181 — your 13-digit CNIC becomes your NTN with no office visit required.', 'Tax', 'Islamabad', 0, 0, 0, 'Official FBR Fee: Rs. 0 (Free) online via iris.fbr.gov.pk (for Individuals) or in person at any Tax House / RTO Facilitation Counter. For Pakistani individuals, your 13-digit CNIC (without dashes) IS your NTN. Under FBR Section 154A, IT & IT-enabled services export proceeds are subject to 1% final tax (0.25% if PSEB-registered; confirm current Finance Act rules on fbr.gov.pk). FBR Helpline: 051-111-772-772 | helpline@fbr.gov.pk.', 'Order issued in minutes to 3 working days after Form 181 submission (100% online)', 'FBR IRIS Online (iris.fbr.gov.pk) & RTO Islamabad (G-9/1)', 'Online 24/7 via iris.fbr.gov.pk for Individuals nationwide. In Islamabad: RTO Islamabad & Tax Facilitation Center, Plot No. 20, Service Road, Mauve Area, Sector G-9/1, Islamabad (Tel: 051-9106387 / TFC: 051-9070000). National Helpline: 051-111-772-772 (Females: 051-9107025) | helpline@fbr.gov.pk.', 'IRIS Online 24/7 (Weekday mornings are fastest) | FBR Helpline Mon–Fri: 8:00 AM – 11:30 PM', 'Weekday morning (IRIS responds faster and SMS/Email PINs arrive quickly)', 'https://iris.fbr.gov.pk/', '2026-11-17T00:00:00Z', TRUE, TRUE, 4) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000005', 'domicile-certificate-rawalpindi', 'Domicile Certificate in Rawalpindi', 'ڈومیسائل سرٹیفکیٹ — راولپنڈی', 'Exact 2026 fee breakdown (Rs. 550 total), required forms (Form P & AC Verification Form), and steps for getting a Domicile Certificate at e-Khidmat Markaz, District Complex, Rawalpindi or via Maryam Ki Dastak.', 'Certificates', 'Rawalpindi', 550, 1450, 1750, 'In Punjab, the 2026 total official fee is Rs. 550 (Rs. 200 fee + Rs. 300 e-affidavit + Rs. 50 PITB charge). If you use Maryam Ki Dastak home delivery, add Rs. 900 to Rs. 1,200 service charge.', '16 working days standard | 2–3 days if Dastak fast track is available in your area', 'e-Khidmat Markaz, District Complex, Rawalpindi', 'e-Khidmat Markaz, District Complex, Rawalpindi. Also available via Maryam Ki Dastak for home delivery.', 'Mon–Sat: 9:00 AM – 5:00 PM (Maryam Ki Dastak home service available)', 'Tuesday to Thursday, 9:00 AM to 11:00 AM', 'https://ekhidmat.punjab.gov.pk/', '2026-11-17T00:00:00Z', TRUE, FALSE, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000006', 'birth-certificate-rawalpindi', 'Birth Certificate from Union Council in Rawalpindi', 'پیدائش کا سرٹیفکیٹ (یونین کونسل) — راولپنڈی', 'How to register a birth and collect a computerized Birth Certificate from your local Union Council, Municipal Committee, or Cantonment Board (NOT NADRA) — completely free within 7 years.', 'Certificates', 'Rawalpindi', 0, 500, 2000, 'Within 7 years: Free (Rs. 0). Late registration after 7 years: Rs. 200 to Rs. 1,000 for Pakistani citizens. Foreign national child: Rs. 2,000. Correction or change in details: Rs. 500. Use the birth certificate afterward to apply for a NADRA Child Registration Certificate (CRC / B-Form): Normal Rs. 50 (7 days) or Executive Rs. 500 (1 day).', 'Same day to 3 days if documents are complete', 'Local Union Council, Municipal Committee, or Cantonment Board', 'Your local Union Council, Municipal Committee, or Cantonment Board in Rawalpindi (NOT NADRA office).', 'Mon–Fri: 9:00 AM – 2:00 PM (Secretary is usually available 9:00 AM – 12:00 PM)', 'Weekday 9:00 AM to 12:00 PM (Secretary is usually available in the morning)', 'https://lgcd.punjab.gov.pk/', '2026-11-17T00:00:00Z', TRUE, FALSE, 6) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000007', 'police-character-certificate-rawalpindi', 'Police Character Certificate in Rawalpindi', 'پولیس کریکٹر سرٹیفکیٹ — راولپنڈی', 'Fast guide to getting your QR-verified Police Character Certificate (Rs. 500, 3 working days courier delivery) from Police Khidmat Markaz at Rescue 15 Liaqat Bagh Metro Station or Punjab centers.', 'Certificates', 'Rawalpindi', 500, 500, 300, 'Police Character Certificate costs Rs. 500 (delivered by courier in 3 working days with QR code for verification). General Police Verification costs Rs. 300 — for foreign visas, always apply for Character Certificate (Rs. 500), not general verification.', '30–45 mins at center | 3 working days courier delivery', 'Police Khidmat Markaz, Rawalpindi (Rescue 15 Liaqat Bagh)', 'Any Police Khidmat Markaz in Punjab. In Rawalpindi: Rescue 15 Office, Liaqat Bagh Metro Station, Murree Road, plus Taxila, Murree, Gujar Khan, and Kahuta centers.', 'Mon–Sat: 8:00 AM – 8:00 PM (Best window: 9:00 AM – 11:00 AM)', 'Weekday 9:00 AM to 11:00 AM', 'https://pkm.punjab.gov.pk/', '2026-11-17T00:00:00Z', TRUE, FALSE, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUD