INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000008', 'child-passport-under-18', 'Child Passport Under 18 in Rawalpindi', 'بچوں کا پاسپورٹ (18 سال سے کم) — راولپنڈی', 'Complete checklist and step-by-step instructions for applying for a minor e-Passport (under 18) at Regional Passport Office Rawalpindi — including parent presence rules and B-Form requirements.', 'Passport', 'Rawalpindi', 9000, 15000, 15000, 'A child’s e-passport uses the same fee table as adults: Rs. 9,000 Normal and Rs. 15,000 Urgent for 36 pages and 5 years. Children under 15 get only 5-year validity.', 'Normal: 21 working days | Urgent: 5 working days (courier delivery)', 'Regional Passport Office, Rawalpindi', 'Regional Passport Office, GT Road, Rawalpindi. Both parents must be present, or one parent with an attested consent affidavit.', 'Mon–Thu: 8:30 AM – 2:00 PM | Fri: 8:30 AM – 12:30 PM', '9:00 AM on a weekday, with both parents', 'https://dgip.gov.pk/', '2026-11-17T00:00:00Z', TRUE, FALSE, 8) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000009', 'name-change-cnic-after-marriage', 'Name Change on CNIC After Marriage', 'شادی کے بعد شناختی کارڈ میں نام کی تبدیلی', 'Official NADRA guide to updating marital status, adding spouse name, and optionally changing surname after marriage — with verified NADRA fees, delivery days, Regulation 41 rules, and PakID app options.', 'Family', 'Rawalpindi', 400, 1150, 2150, 'Official NADRA modification fees (nadra.gov.pk/feeStructure): Ordinary CNIC is Rs. 400 Normal (15 days), Rs. 1,150 Urgent (12 days), Rs. 2,150 Executive (6 days). Smart CNIC (SNIC) is Rs. 750 Normal (31 days), Rs. 1,500 Urgent (23 days), Rs. 2,500 Executive (9 days). Updating non-printable fields only (marital status in NADRA database without a new printed card) is Rs. 100 at NRC (2 days) or USD 5 via PakID app (2 days). Optional FRC afterward: Rs. 1,000 (1 day). 24/7 NADRA Helpline: 1777.', '45 mins at center | Ordinary: 15/12/6 days | Smart: 31/23/9 days | DB-Only: 2 days', 'NADRA Mega Center, Saddar, Rawalpindi', 'NADRA Mega Center, Saddar, Rawalpindi (or any NADRA Registration Centre / official PakID mobile app). 24/7 NADRA Helpline: 1777 / +92 51 111 786 100.', 'Mon–Sat: 8:00 AM – 8:00 PM (PakID app available 24/7)', 'Weekday morning (9:00 AM – 11:00 AM)', 'https://www.nadra.gov.pk/feeStructure', '2026-11-17T00:00:00Z', TRUE, TRUE, 9) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000010', 'e-challan-check-and-payment', 'E-Challan Check and Payment in Punjab', 'پنجاب ای چالان چیک اور ادائیگی', 'Check and pay Punjab Safe Cities (PSCA) traffic e-Challans online in 2 minutes via echallan.psca.gop.pk and e-Pay Punjab 17-digit PSID — with common violation fines and SMS scam warnings.', 'Driving', 'Lahore', 2000, 5000, 10000, 'Fine depends on violation. Common Punjab fines: No helmet Rs. 2,000; Red light Rs. 2,000 to Rs. 5,000; No licence Rs. 5,000; Overspeeding Rs. 2,000 to Rs. 10,000. Check your exact fine on echallan.psca.gop.pk and pay within 10 days to avoid extra penalty.', 'Check takes 2 mins | Payment reflects on portal in 10 mins to 2 hours', 'Online Only — PSCA E-Challan Portal (echallan.psca.gop.pk)', 'Online only at echallan.psca.gop.pk. No need to visit an office.', 'Online 24 hours / 7 days a week', 'Anytime — portal is open 24 hours (pay within 10 days to avoid extra penalty)', 'https://echallan.psca.gop.pk/', '2026-11-17T00:00:00Z', TRUE, TRUE, 10) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
INSERT INTO public.processes (id, slug, title, urdu_title, summary, category, city, fee_normal, fee_urgent, fee_executive, fee_notes, time_required, office_name, office_address, office_timings, best_day_to_go, official_source_url, last_updated, is_verified, is_nationwide, popularity_rank) VALUES ('a1000000-0000-4000-8000-000000000011', 'cnic-renewal-islamabad', 'CNIC Renewal in Islamabad', 'شناختی کارڈ کی تجدید — اسلام آباد', 'Official NADRA guide to renewing your Smart CNIC (SNIC) or Ordinary CNIC in Islamabad at NADRA Mega Center, Blue Area (Khyber Plaza), Islamabad or via the PakID mobile app — verified fees, delivery days, Rule 12 requirements, and local center addresses.', 'Identity', 'Islamabad', 750, 1500, 2500, 'Official NADRA renewal fees nationwide (nadra.gov.pk/feeStructure): Smart CNIC (SNIC) is Rs. 750 Normal (31 days), Rs. 1,500 Urgent (23 days), and Rs. 2,500 Executive (9 days). Ordinary CNIC (Teslin) is Rs. 400 Normal (15 days), Rs. 1,150 Urgent (12 days), and Rs. 2,150 Executive (6 days). No gazetted attestation is required for renewal (Rule 12). 24/7 NADRA Helpline: 1777 or +92 51 111 786 100.', '35–75 mins at Blue Area Mega Center | Smart: 31/23/9 days | Ordinary: 15/12/6 days', 'NADRA Mega Center, Blue Area (Khyber Plaza), Islamabad', '98-West, Khyber Plaza, Jinnah Avenue, Blue Area, Islamabad (3 shifts, open Saturday). Other centers: RHO/PHQ G-10/4 (Plot 30, Mauve Area), Asaan Khidmat Center G-9/1, PFC F-6/1 & G-11/4, or PakID app. 24/7 Helpline: 1777.', 'Mega Center Blue Area: 3 Shifts / 24-Hour Operations (Mon–Sat) | RHO G-10/4: Mon–Fri 8:30 AM – 4:30 PM | PakID 24/7', 'Tuesday to Thursday, 8:30 AM – 10:30 AM or late evening shift at Blue Area Mega Center (avoid Saturday midday)', 'https://www.nadra.gov.pk/feeStructure', '2026-11-17T00:00:00Z', TRUE, FALSE, 11) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
