EXCLUDED.title, urdu_title = EXCLUDED.urdu_title, summary = EXCLUDED.summary, category = EXCLUDED.category, city = EXCLUDED.city, fee_normal = EXCLUDED.fee_normal, fee_urgent = EXCLUDED.fee_urgent, fee_executive = EXCLUDED.fee_executive, fee_notes = EXCLUDED.fee_notes, time_required = EXCLUDED.time_required, office_name = EXCLUDED.office_name, office_address = EXCLUDED.office_address, office_timings = EXCLUDED.office_timings, best_day_to_go = EXCLUDED.best_day_to_go, official_source_url = EXCLUDED.official_source_url, last_updated = EXCLUDED.last_updated, is_verified = EXCLUDED.is_verified, is_nationwide = EXCLUDED.is_nationwide, popularity_rank = EXCLUDED.popularity_rank;
