INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1230000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000023', 'Personal Email Address Belonging to You', 'original', 1, 'Receives the Email verification code alongside your IRIS login password and 4-digit PIN.', 3) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, copies_needed = EXCLUDED.copies_needed, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1230000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000023', 'Personal Bank Account Maintenance Certificate (Scanned PDF)', 'photocopy', 1, 'Official FBR requirement: bank account maintenance certificate in your own name for Form 181 attachment.', 4) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, copies_needed = EXCLUDED.copies_needed, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1230000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000023', 'Business Premises Ownership/Tenancy Proof & Paid Utility Bill <= 3 Months (For Businesses)', 'photocopy', 1, 'Required if registering a business or visiting Regional Tax Office (RTO) Hyderabad & FBR IRIS Online for AOP/sole-proprietor enrollment.', 5) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, copies_needed = EXCLUDED.copies_needed, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1240000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000024', 'Valid Original CNIC + Front & Back Scan (PDF or JPG Under 2MB)', 'photocopy', 1, 'Your 13-digit CNIC (without dashes) serves as your Individual NTN / IRIS Registration Number.', 1) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, copies_needed = EXCLUDED.copies_needed, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1240000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000024', 'Active Mobile SIM Registered on Your Own CNIC', 'original', 1, 'Mandatory under FBR rules — IRIS SMS verification fails if the mobile SIM is registered to another CNIC.', 2) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, copies_needed = EXCLUDED.copies_needed, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1240000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000024', 'Personal Email Address Belonging to You', 'original', 1, 'Receives the Email verification code alongside your IRIS login password and 4-digit PIN.', 3) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, copies_needed = EXCLUDED.copies_needed, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1240000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000024', 'Personal Bank Account Maintenance Certificate (Scanned PDF)', 'photocopy', 1, 'Official FBR requirement: bank account maintenance certificate in your own name for Form 181 attachment.', 4) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, copies_needed = EXCLUDED.copies_needed, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;
INSERT INTO public.documents (id, process_id, name, type, copies_needed, note, sort_order) VALUES ('d1240000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000024', 'Business Premises Ownership/Tenancy Proof & Paid Utility Bill <= 3 Months (For Businesses)', 'photocopy', 1, 'Required if registering a business or visiting Regional Tax Office (RTO) Multan & Tax Facilitation Center for AOP/sole-proprietor enrollment.', 5) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, copies_needed = EXCLUDED.copies_needed, note = EXCLUDED.note, sort_order = EXCLUDED.sort_order;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 1, 'Go to Token Counter & Get Renewal Token', 'Arrive at Regional Passport Office, GT Road, Rawalpindi (best window: Tuesday to Thursday, 8:30 AM to 10:00 AM) and get a token for e-passport renewal.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 2, 'Biometric Verification & Photo at Counter', 'Complete biometric verification and have your live photograph taken at the counter. Do not bring your own photo — photos are captured directly at the office.', 20) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000001', 3, 'Pay Fee via Bank Counter or PSID', 'Pay the official e-passport fee at the bank counter inside the office or online via PSID (5-year 36-page e-passport: Rs. 9,000 Normal or Rs. 15,000 Urgent; 10-year: Rs. 13,500 Normal or Rs. 22,500 Urgent).', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1010000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000001', 4, 'Collect Receipt with Tracking ID & Track on dgip.gov.pk', 'Collect your receipt with the tracking ID and track your application status on dgip.gov.pk. Delivery takes 21 working days (Normal), 5 working days (Urgent), or 2 working days (Executive at Executive Offices).', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 1, 'Visit NADRA Center or Use Official PakID App', 'Under Rule 12 (NADRA NIC Rules, 2002), apply anytime up to 1 month after expiry with no attestation required. Visit NADRA Mega Center, Saddar, Rawalpindi (weekday 9:00 AM – 11:00 AM is best) and take a renewal token, or apply online via the official PakID app.', 35) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 2, 'Biometrics, Photo & Signature at Counter', 'NADRA updates your biometrics, live photograph, and signature at renewal (your previous card is surrendered/punched). Double-check the spelling of your name and father’s name on screen before final submit, and provide a mobile SIM registered on your own CNIC.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000002', 3, 'Pay Official Renewal Fee at Cash Counter', 'Pay at the fee counter — Smart CNIC (SNIC): Rs. 750 Normal (31 days) / Rs. 1,500 Urgent (23 days) / Rs. 2,500 Executive (9 days); Ordinary CNIC: Rs. 400 Normal (15 days) / Rs. 1,150 Urgent (12 days) / Rs. 2,150 Executive (6 days).', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1020000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000002', 4, 'Get Tracking Slip & Track via PakID or Helpline 1777', 'Take your tracking slip and snap a photo of it immediately so you do not lose it. Track status via the PakID app or 24/7 NADRA Helpline 1777, then collect your renewed card or opt for home delivery.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 1, 'Open Dastak App or Go to Police Khidmat Markaz', 'Open the Dastak Punjab app / DLIMS online (takes ~10 mins) or visit Police Khidmat Markaz, Rawalpindi between 9:00 AM and 11:00 AM on a weekday (20–30 mins if documents are ready).', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 2, 'Select Renewal & Upload Photo + Old Licence Copy', 'Choose Driving Licence Renewal, verify your current home delivery address carefully, and upload/submit your fresh white-background photo and old licence copy.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 3, 'Generate PSID Challan & Pay Within 24 Hours', 'Generate the PSID challan (Car: Rs. 1,830 with courier; Motorcycle: Rs. 930 with courier; LTV/HTV: Rs. 2,330 with courier) and pay within 24 hours via JazzCash, Easypaisa, bank app, or ATM.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1030000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000003', 4, 'Receive New Licence at Home by Courier', 'Your renewed driving licence is printed and delivered directly to your home address by courier within 7 to 10 days.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000004', 1, 'Open iris.fbr.gov.pk & Click "Registration for Unregistered Person"', 'Go to iris.fbr.gov.pk (weekday mornings are fastest) and click "Registration for Unregistered Person" for a new individual registration. (Only use "E-Enrollment for Registered Person" if you already held an older NTN.)', 3) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004', 2, 'Verify Separate SMS & Email Codes to Get IRIS Password & PIN', 'Enter your 13-digit CNIC (without dashes), mobile SIM registered against your own CNIC, and active personal email. Enter the separate SMS and Email verification codes to receive your IRIS Password and PIN.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 3, 'Log In & Open Draft → Registration → Form 181', 'Log in to IRIS using your 13-digit CNIC and password, open Draft → Registration → "181 (Form of Registration filed voluntarily)" and click Edit. Fill your residential address, accounting period, principal activity (Freelancer / IT & IT-Enabled Services), and bank account details.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000004', 4, 'Upload Official PDF Attachments & Submit Form 181', 'Under Attachments, upload your scanned bank account maintenance certificate PDF in your own name (plus business premises tenancy/ownership proof and a paid utility bill not older than 3 months if running a business) and click Submit.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1040000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000004', 5, 'Download Form 181 Registration Order from Completed Tasks', 'Save your IRIS password and PIN securely. Within minutes to 3 working days, open Completed Tasks for "181 (Order to grant / refuse registration on application)" — your 13-digit CNIC is now your active NTN and you can file Income Tax Return (Form 114).', 2) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', 1, 'Get Form P & AC Verification Form from Center', 'Visit e-Khidmat Markaz, District Complex, Rawalpindi (Tuesday to Thursday, 9:00 AM – 11:00 AM) and collect both Form P and the AC Verification Form.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000005', 2, 'Fill Forms & Get Rs. 300 Affidavit Made at Center', 'Fill in Form P and the AC Verification Form accurately (ensuring residence address matches your CNIC/proof) and get your Rs. 300 e-affidavit prepared at the center.', 20) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000005', 3, 'Submit File & Pay Rs. 550 via e-Pay or Challan', 'Submit your complete document file (including parent/spouse CNIC copy, 2 photos, and residence proof) and pay the Rs. 550 total 2026 fee (Rs. 200 fee + Rs. 300 e-affidavit + Rs. 50 PITB charge) via e-Pay or challan.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1050000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000005', 4, 'Collect Tracking Slip & Certificate (16 Working Days)', 'Take your tracking slip. Your computerized Domicile Certificate is ready in 16 working days standard (or 2 to 3 days if Maryam Ki Dastak fast track is available in your area).', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 1, 'Go to Union Council Secretary With Parents’ CNICs', 'Visit your local Union Council, Municipal Committee, or Cantonment Board Secretary between 9:00 AM and 12:00 PM with both parents’ original CNICs and copies (do NOT go to NADRA first).', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', 2, 'Fill Birth Registration Form & Triple-Check Spelling', 'Fill out the birth registration form and verify the spelling of the child’s name, date of birth, and parents’ names 3 times — mistakes cause major problems for B-Form and passport later.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000006', 3, 'System Entry & Collect Computerized Birth Certificate', 'The Secretary enters the record into the system. Timely registration within 7 years is FREE, and you receive the computerized birth certificate the same day or in 2 to 3 days.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1060000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000006', 4, 'Use Certificate to Apply for B-Form (CRC) at NADRA', 'Take your computerized Union Council birth certificate to NADRA to apply for your child’s CRC / B-Form. Official NADRA CRC fees: Normal Rs. 50 (7 days) or Executive Rs. 500 (1 day). Remember CRC expires at ages 3, 10, and 18.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000007', 1, 'Go to Any Khidmat Markaz & Take Character Certificate Token', 'Visit Rescue 15 Office (Liaqat Bagh Metro Station, Murree Road) or any Punjab Police Khidmat Markaz (Taxila, Murree, Gujar Khan, Kahuta) between 9:00 AM and 11:00 AM and take a token specifically for "Character Certificate".', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000007', 2, 'Fill Form, Give Biometrics & Photo', 'Complete the application form with your CNIC, passport details (for visa), and matching current address, then complete biometrics and live photo.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', 3, 'Pay Rs. 500 at Counter & Get Tracking Slip', 'Pay the official Rs. 500 Character Certificate fee at the counter (not Rs. 300 general verification) and collect your tracking slip.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1070000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000007', 4, 'Receive QR-Verified Certificate by Courier in 3 Working Days', 'Your original Police Character Certificate with a scannable QR code for verification is delivered to your address by courier in 3 working days.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000008', 1, 'Both Parents & Child Go to Passport Office', 'Visit Regional Passport Office, Rawalpindi at 9:00 AM on a weekday with both parents and the child (or one parent carrying an attested consent affidavit from the absent parent).', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000008', 2, 'Take Token for Minor & Complete Biometrics', 'Collect a minor passport token. Biometrics are taken for both parents, and also for the child if age 10 or older.', 20) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000008', 3, 'Child Photo Taken at Office', 'The child’s photograph is captured live at the Passport Office counter — you do not need to bring studio photos.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000008', 4, 'Pay Fee & Collect Tracking Slip', 'Pay the e-passport fee (Rs. 9,000 Normal or Rs. 15,000 Urgent for 36 pages, 5 years) and keep your printed tracking slip safely.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1080000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000008', 5, 'Passport Delivered by Courier', 'Your child’s e-passport is delivered by courier — Normal takes 21 working days and Urgent takes 5 working days.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000009', 1, 'Get Computerized Marriage Certificate (MRC) from Union Council', 'First obtain your computerized Marriage Registration Certificate (MRC) from your local Union Council. Under NADRA Regulation 41, this plus your spouse’s CNIC/POC/Passport is strictly mandatory — a manual Nikahnama alone is not accepted.', 30) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000009', 2, 'Visit NADRA Center or Use Official PakID App', 'Visit NADRA Mega Center, Saddar, Rawalpindi on a weekday morning (or apply via the official PakID app) and take a token for CNIC Modification (or Non-Printable Field Update if only updating marital status in the database).', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000009', 3, 'Present MRC & Confirm Name Preference Clearly', 'Present your computerized MRC and spouse CNIC copy. Tell the operator clearly whether you want to keep your father’s name (your legal right) or add your husband’s name/surname, and update marital status to Married for both spouses so FRC matches later.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000009', 4, 'Biometrics, Live Photo & On-Screen Verification', 'Complete biometrics, live photo, and signature at the counter, surrender/punch your previous card if getting a new printed CNIC, and verify all English & Urdu spellings carefully on screen.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1090000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000009', 5, 'Pay Official NADRA Fee & Save Tracking Slip', 'Pay at the counter — Ordinary CNIC: Rs. 400 Normal (15 days) / Rs. 1,150 Urgent (12 days) / Rs. 2,150 Executive (6 days); Smart CNIC: Rs. 750 (31 days) / Rs. 1,500 (23 days) / Rs. 2,500 (9 days); or DB-only marital status update: Rs. 100 at NRC (2 days) / USD 5 on PakID (2 days).', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000010', 1, 'Open Official Portal: echallan.psca.gop.pk', 'Type echallan.psca.gop.pk directly into your browser yourself — NEVER click links sent via SMS, as many are scams.', 1) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000010', 2, 'Enter Vehicle Number + Owner CNIC or Chassis Number', 'Enter your vehicle registration number (e.g., LEA-1234) and the owner’s 13-digit CNIC (without dashes) or chassis number, then tap Search.', 1) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000010', 3, 'Select Challan & Generate 17-Digit PSID in e-Pay Punjab', 'If an unpaid challan exists, select it and generate a 17-digit PSID code in the e-Pay Punjab app.', 2) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000010', 4, 'Pay PSID Within 24 Hours via App, ATM, or Counter', 'Pay your 17-digit PSID through JazzCash, Easypaisa, your bank app, a 1Link ATM, or over the counter within 24 hours before the PSID expires.', 2) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1100000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000010', 5, 'Save Screenshot of Payment Receipt', 'Save a screenshot of your payment receipt. Payment confirmation takes 10 minutes to 2 hours to reflect on the PSCA portal.', 1) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1110000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000011', 1, 'Apply via PakID App OR Visit NADRA Mega Center, Blue Area (Khyber Plaza), Islamabad', 'Start online via NADRA’s official PakID mobile app, or walk into NADRA Mega Center, Blue Area (Khyber Plaza), Islamabad (or any alternative center in Islamabad: RHO/PHQ G-10/4 (Plot #30, Mauve Area), Asaan Khidmat Center G-9/1 (open Saturday), and Public Facilitation Centers in F-6/1 & G-11/4) and take a queue token with your original old CNIC.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1110000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000011', 2, 'Biometric Scan, Live Photo & On-Screen Data Check', 'When your token is called, complete fingerprints and live photo capture, surrender/punch your previous card, and carefully inspect your English and Urdu name, father’s name, and address on the operator’s screen.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1110000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000011', 3, 'Pay Official NADRA Fee at Counter (or Digital PSID)', 'Choose Smart CNIC (Rs. 750 Normal 31 days | Rs. 1,500 Urgent 23 days | Rs. 2,500 Executive 9 days) or Ordinary CNIC (Rs. 400 Normal 15 days | Rs. 1,150 Urgent 12 days | Rs. 2,150 Executive 6 days). Always take a photo of your tracking receipt.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1110000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000011', 4, 'Track SMS/PakID Status & Collect Your Renewed CNIC', 'Track delivery via the PakID app or SMS alerts on your own SIM, then collect your renewed card from the Islamabad NADRA delivery counter (or home courier if selected on PakID). For issues, call 24/7 Helpline 1777.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1120000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000012', 1, 'Apply via PakID App OR Visit NADRA Mega Center, Egerton Road (Shimla Pahari), Lahore', 'Start online via NADRA’s official PakID mobile app, or walk into NADRA Mega Center, Egerton Road (Shimla Pahari), Lahore (or any alternative center in Lahore: Mega Center Peco Road (Quaid-e-Azam Town), Mega Center 15-A Sanda Road, DHA Phase 1 & Phase 4 (2 shifts), and RHO Lahore (73 Trade Centre, Johar Town)) and take a queue token with your original old CNIC.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1120000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000012', 2, 'Biometric Scan, Live Photo & On-Screen Data Check', 'When your token is called, complete fingerprints and live photo capture, surrender/punch your previous card, and carefully inspect your English and Urdu name, father’s name, and address on the operator’s screen.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
