INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1170000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000017', 1, 'Apply via PakID App OR Visit NADRA Registration Center, Bosan Road & Executive Centre ChenOne Tower, Multan', 'Start online via NADRA’s official PakID mobile app, or walk into NADRA Registration Center, Bosan Road & Executive Centre ChenOne Tower, Multan (or any alternative center in Multan: Executive Centre ChenOne Tower (3rd Floor, Abdali Road), Multan Cantt (Shop 15–16, Ali Arcade, Katchehry Chowk — 2 shifts), M.A. Jinnah Road (2 shifts), Mumtazabad (2 shifts), and RHO Multan (221-A Shah Rukn-e-Alam Colony)) and take a queue token with your original old CNIC.', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
