INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1170000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000017', 4, 'Track SMS/PakID Status & Collect Your Renewed CNIC', 'Track delivery via the PakID app or SMS alerts on your own SIM, then collect your renewed card from the Multan NADRA delivery counter (or home courier if selected on PakID). For issues, call 24/7 Helpline 1777.', 15) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1180000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000018', 1, 'Open FBR IRIS Portal (iris.fbr.gov.pk) & Select Registration for Unregistered Person', 'Visit https://iris.fbr.gov.pk/ and click "Registration for Unregistered Person" (free Rs. 0 for Individuals across Rawalpindi). If registering an AOP or Company, visit Regional Tax Office (RTO) Rawalpindi & FBR IRIS Online in person.', 3) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1180000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000018', 2, 'Enter CNIC, Own-CNIC Mobile Number & Email for Dual OTP Verification', 'Enter your 13-digit CNIC (without dashes), full name, mobile carrier + SIM registered strictly on your own CNIC, and personal email. Verify BOTH the SMS code and Email code to receive your IRIS password and 4-digit PIN.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1180000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000018', 3, 'Log In to IRIS & Complete Form 181 (Registration Application)', 'Log in to IRIS with your CNIC and password, open Registration -> 181 (Form of Registration filed voluntarily), and fill in your Rawalpindi residential address, bank IBAN, and income source (salaried, freelancer, or business).', 10) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1180000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000018', 4, 'Attach Scanned Docs Under 2MB & Submit With 4-Digit PIN', 'Upload your CNIC scan and bank account maintenance certificate PDF (plus tenancy/utility bill <= 3 months if registering a business), verify with your 4-digit PIN, and click Submit.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1180000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000018', 5, 'Download Form 181 Order (or Get Free Help at RTO Rawalpindi)', 'Open Completed Tasks -> 181 (Order to grant registration) to download your free NTN Registration Certificate — your 13-digit CNIC is your NTN. Need biometric or IRIS login help? Visit Regional Tax Office (RTO) Rawalpindi & FBR IRIS Online (Tel: 051-9270405) or call 051-111-772-772.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1190000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000019', 1, 'Open FBR IRIS Portal (iris.fbr.gov.pk) & Select Registration for Unregistered Person', 'Visit https://iris.fbr.gov.pk/ and click "Registration for Unregistered Person" (free Rs. 0 for Individuals across Lahore). If registering an AOP or Company, visit Regional Tax Office (RTO) Lahore — Tax House & FBR IRIS Online in person.', 3) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
INSERT INTO public.steps (id, process_id, step_number, title, description, time_minutes) VALUES ('e1190000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000019', 2, 'Enter CNIC, Own-CNIC Mobile Number & Email for Dual OTP Verification', 'Enter your 13-digit CNIC (without dashes), full name, mobile carrier + SIM registered strictly on your own CNIC, and personal email. Verify BOTH the SMS code and Email code to receive your IRIS password and 4-digit PIN.', 5) ON CONFLICT (id) DO UPDATE SET step_number = EXCLUDED.step_number, title = EXCLUDED.title, description = EXCLUDED.description, time_minutes = EXCLUDED.time_minutes;
