INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11010000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'Bringing an Expired CNIC', 'Your CNIC must be valid on the day of your application. If your CNIC is expired, renew it at NADRA first before visiting the Passport Office.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11010000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 'Bringing Your Own Photo (Wrong Photo)', 'Do not bring your own studio photo — your live passport photograph is captured directly at the Passport Office counter.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11010000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000001', 'Going After 11:00 AM on Monday', 'Monday is the most crowded day — going after 11:00 AM on Monday means waiting 2 hours extra. Visit Tuesday to Thursday between 8:30 AM and 10:00 AM instead.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11020000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'Using Someone Else’s Mobile Number', 'Always use a mobile SIM registered on your own CNIC so verification and delivery tracking SMS messages arrive properly.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11020000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 'Not Checking Spelling of Name & Father’s Name on Screen', 'Carefully check the spelling of your name and father’s name on the operator’s screen before final submit — errors after printing require a new modification fee.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11020000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000002', 'Losing Your Tracking Slip', 'Take a photo of your tracking slip immediately at the counter so you never lose your tracking ID before card collection.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11030000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 'Letting Licence Expire More Than 3 Months', 'Late renewal adds extra fines: for a car licence, the late fine is Rs. 675 for 1 to 3 months late, and Rs. 1,350 for 3 to 6 months late.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11030000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 'Using an Old Address', 'Your new driving licence is delivered by courier — if your address is wrong or outdated, courier delivery will fail.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11030000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'Not Paying PSID Within 24 Hours', 'Your generated PSID challan expires after 24 hours, forcing you to generate a new PSID and start payment again.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11040000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000004', 'Using a SIM Not Registered on Your Own CNIC', 'FBR verifies SIM ownership against NADRA records — IRIS SMS code verification will fail if the SIM is not registered against your own CNIC.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11040000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004', 'Stopping After Account Creation Without Submitting Form 181', 'Getting your IRIS password is only Step 1 — you MUST log in, open Draft → Registration → Form 181, upload attachments, and Submit to receive your 181 Registration Order in Completed Tasks (otherwise you cannot file Form 114 returns).', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11040000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 'Using a Fake Address or Losing Your IRIS Password & PIN', 'Never enter a fake business address (FBR can verify premises), and save both your IRIS password and PIN securely — you need them every year to file tax returns.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11050000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', 'Bringing Only Your Own CNIC', 'You also need a copy of your father’s, mother’s, or spouse’s CNIC — bringing only your own CNIC is not sufficient.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11050000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000005', 'Wrong Address on Proof of Residence', 'The address on your property papers, utility bill, rent agreement, or voter list entry must match your CNIC or declared address.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11050000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000005', 'Forgetting the AC Verification Form', 'The AC Verification Form (available at the center) is mandatory — your domicile file will be returned without it.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11060000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 'Spelling Mistake in Child’s Name', 'A spelling error in the child’s name will cause problems for B-Form, school records, and passport later. Check the spelling 3 times before submission.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11060000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', 'Not Registering Within 7 Years', 'Birth registration is completely FREE within 7 years — waiting past 7 years means paying a Rs. 200 to Rs. 1,000 late fee and providing extra affidavit and proof of birth documents.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11060000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000006', 'Going to NADRA First', 'NADRA does NOT issue birth certificates — your local Union Council, Municipal Committee, or Cantonment Board issues the birth certificate first.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11070000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000007', 'Confusing Character Certificate With General Police Verification', 'For visas and embassies you need a Police Character Certificate (Rs. 500), NOT General Police Verification (Rs. 300).', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11070000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000007', 'CNIC Address Not Matching Your Current Address', 'Your CNIC address must match your current address — update your address with NADRA first if you moved.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11070000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', 'Applying at the Last Minute', 'Embassies require the original QR-coded certificate (photocopies are not accepted), so apply early and allow 3 working days for courier delivery.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11080000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000008', 'Coming With Only One Parent and No Affidavit', 'Both parents must be present — if one parent is absent, you must bring an attested consent affidavit from the absent parent or the file will be rejected.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11080000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000008', 'Outdated B-Form / CRC Missing Photo, IRIS, or Fingerprints', 'Under official NADRA CRC rules, children aged 3–10 need Photo + IRIS on their CRC, and children aged 10–17 MUST have Photo + Fingerprints + IRIS (under 3 needs Photo for passport) — otherwise you will be sent back to NADRA first.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11080000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000008', 'Expired Parent CNIC', 'Both father’s and mother’s CNICs must be valid — an expired parent CNIC blocks the child’s passport application.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11090000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000009', 'Going to NADRA Without a Computerized Marriage Certificate', 'A manual Nikahnama is not enough — you must first get a computerized Marriage Registration Certificate (MRC) from your Union Council.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11090000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000009', 'Not Updating Both Husband and Wife Records', 'Update marital status for both husband and wife — otherwise your Family Registration Certificate (FRC) will not match later for visas.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11090000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000009', 'Trying to Change Name Back Later', 'NADRA allows a name change only once in a lifetime (except after marriage), so be certain before changing your surname.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11100000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000010', 'Paying via a Link Sent in SMS', 'Many SMS links claiming you have an unpaid e-challan are scams. Always type echallan.psca.gop.pk directly into your browser yourself.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11100000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000010', 'Not Paying PSID Within 24 Hours', 'Your 17-digit PSID expires after 24 hours — if you miss the window, you will have to generate a fresh PSID again.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11100000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000010', 'Ignoring an Unpaid E-Challan', 'Unpaid challans attract extra penalties after 10 days and will block your vehicle transfer and driving licence renewal later.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11110000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000011', 'Giving a Mobile Number Registered on Someone Else’s CNIC', 'Always provide a SIM registered against your own CNIC so NADRA verification and card-ready SMS notifications arrive reliably.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11110000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000011', 'Skipping the On-Screen Spelling Check Before Final Submit', 'Check every letter of your English & Urdu name, father’s name, and address on the counter screen before approving — fixing typos after printing requires paying a fresh modification fee.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11110000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000011', 'Paying Agents or Seeking Unnecessary Attestation', 'Under NADRA Rule 12, CNIC renewal requires ZERO gazetted attestation and zero agent fees — apply directly at official Islamabad NADRA centers or on the official PakID app.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
