INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11180000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000018', 'Using a Mobile SIM Not Registered on Your Own CNIC', 'FBR IRIS cross-checks SIM ownership against your CNIC — using a family member’s SIM causes instant registration failure.', 1) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11180000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000018', 'Paying Middlemen for a Free Online Registration', 'Individual NTN registration on iris.fbr.gov.pk and at Regional Tax Office (RTO) Rawalpindi & FBR IRIS Online is 100% free (Rs. 0). Never pay agents for basic Form 181 enrollment.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11180000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000018', 'Confusing NTN Enrollment With Active Taxpayer List (ATL) Filer Status', 'Getting your Form 181 NTN order registers you with FBR, but you only appear on the Active Taxpayer List (ATL) and get lower withholding tax rates after filing your annual Income Tax Return.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
