INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11240000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000024', 'Paying Middlemen for a Free Online Registration', 'Individual NTN registration on iris.fbr.gov.pk and at Regional Tax Office (RTO) Multan & Tax Facilitation Center is 100% free (Rs. 0). Never pay agents for basic Form 181 enrollment.', 2) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.mistakes (id, process_id, title, description, sort_order) VALUES ('11240000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000024', 'Confusing NTN Enrollment With Active Taxpayer List (ATL) Filer Status', 'Getting your Form 181 NTN order registers you with FBR, but you only appear on the Active Taxpayer List (ATL) and get lower withholding tax rates after filing your annual Income Tax Return.', 3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'Can I still apply for an old Machine Readable Passport (MRP)?', 'No. Since Oct 2026, Pakistan issues only e-passports and MRP is discontinued. All new renewals are issued as e-passports.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 'What is the fee for a 5-year vs 10-year 36-page e-Passport?', 'For a 36-page e-passport: 5 years costs Rs. 9,000 (Normal) or Rs. 15,000 (Urgent); 10 years costs Rs. 13,500 (Normal) or Rs. 22,500 (Urgent).', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000001', 'Can I renew my passport online instead of visiting GT Road Rawalpindi?', 'Yes, passport renewal is also available online via the official DGIP portal (dgip.gov.pk). If visiting in person, go to Regional Passport Office, GT Road, Rawalpindi between Tuesday and Thursday, 8:30 AM to 10:00 AM.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000001', 'Do I need to bring passport-size photographs?', 'No! Do not bring your own photo — your photograph is taken live at the Passport Office counter during biometric verification.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1010000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000001', 'How long does delivery take and how do I track my passport?', 'Normal takes 21 working days, Urgent takes 5 working days, and Executive takes 2 working days at Executive Offices. Keep your receipt with tracking ID and check status on dgip.gov.pk.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'What is the official fee & delivery difference between Smart CNIC and Ordinary CNIC renewal?', 'Per nadra.gov.pk/feeStructure: Smart CNIC (SNIC) renewal is Rs. 750 Normal (31 days), Rs. 1,500 Urgent (23 days), and Rs. 2,500 Executive (9 days). Ordinary CNIC (Teslin) renewal is Rs. 400 Normal (15 days), Rs. 1,150 Urgent (12 days), and Rs. 2,150 Executive (6 days).', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 'Can I renew my CNIC online without visiting Saddar Mega Center?', 'Yes! You can apply online through NADRA’s official PakID mobile app (Google Play & App Store) and track status in-app, though NADRA notes that biometric verification or live photograph capture may require visiting a NADRA Registration Centre (NRC) if needed.', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000002', 'Do I need gazetted officer attestation or when must I renew my CNIC?', 'No attestation is required for CNIC renewal. Under Rule 12 of NADRA (NIC) Rules, 2002, citizens can apply for renewal anytime up to 1 month after expiry. Expect 45 mins–1.5 hrs wait at Saddar Mega Center on weekdays (9–11 AM), or 2+ hrs on Saturday.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000002', 'What extra documents are needed if my address or marital status changed?', 'If your address changed, bring a utility bill or rent agreement. If your marital status changed, under NADRA Regulation 41 bring your Union Council computerized Marriage Certificate (MRC) and spouse’s CNIC copy.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1020000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000002', 'How do I contact NADRA or track my renewal application?', 'Use a mobile SIM registered on your own CNIC, snap a photo of your tracking slip at the counter, and track via the PakID app or NADRA’s 24/7 Helpline: 1777 (mobile) / +92 51 111 786 100 (landline) / csd@nadra.gov.pk.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 'What is the total driving licence renewal fee in Punjab including courier?', 'With the Rs. 480 courier fee included, 1-year renewal costs Rs. 930 for Motorcycle (Rs. 450 fee), Rs. 1,830 for Car / Jeep (Rs. 1,350 fee), and Rs. 2,330 for LTV / HTV (Rs. 1,850 fee).', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000003', 'Can I renew my Punjab driving licence completely online?', 'Yes! You can apply online in about 10 minutes via the Dastak Punjab app or DLIMS portal, pay the PSID challan through JazzCash, Easypaisa, bank app, or ATM, and receive your licence by courier in 7 to 10 days.', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'What is the late fine if my car driving licence has expired?', 'For a car licence in Punjab, late renewal adds a fine of Rs. 675 if 1 to 3 months late, and Rs. 1,350 if 3 to 6 months late.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000003', 'When do I need a medical certificate for renewal?', 'A medical certificate is required if you are over 60 years old or if you are renewing after a long expiry.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1030000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000003', 'What happens if I do not pay the PSID within 24 hours?', 'A Punjab PSID challan expires after 24 hours, so you will have to generate a fresh PSID and pay again. Also double-check your delivery address so courier delivery does not fail.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000004', 'Does FBR NTN registration cost anything, and who can register online?', 'No! FBR individual registration on iris.fbr.gov.pk (and in person at any Tax House / RTO Facilitation Counter) is 100% free (Rs. 0). Online IRIS registration is available for Individuals only — AOPs and Companies must visit a Tax House / RTO Facilitation Counter.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000004', 'What will my NTN number be after submitting Form 181?', 'For Pakistani individuals, your 13-digit CNIC (without dashes) IS your NTN / IRIS Registration Number (7-digit NTNs are only for AOPs, Companies, and non-Pakistanis). After submitting Form 181, check Completed Tasks for "181 (Order to grant / refuse registration on application)".', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 'What official documents does FBR require for individual registration?', 'Per fbr.gov.pk: valid original CNIC, a mobile SIM registered against your own CNIC, personal email address, scanned PDF of personal bank account maintenance certificate in your own name, and (if running a business) tenancy/ownership proof + paid business utility bill not older than 3 months.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000004', 'What tax rate applies to Pakistani freelancers / IT exporters under FBR Section 154A?', 'Under Section 154A of the Income Tax Ordinance, IT and IT-enabled services export proceeds brought through banking channels are subject to 1% final tax, reduced to 0.25% final tax if registered with PSEB (Pakistan Software Export Board) and meeting filing conditions. Always confirm current Finance Act rates on fbr.gov.pk.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1040000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000004', 'What if I face an error on IRIS or need official FBR help?', 'Try weekday mornings when IRIS is faster and OTPs arrive reliably. For official support, call the FBR National Helpline at 051-111-772-772 (Exclusive Line for Females: 051-9107025, Mon–Fri) or email helpline@fbr.gov.pk.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', 'What is the exact 2026 Domicile Certificate fee in Punjab?', 'The total official 2026 fee in Punjab is Rs. 550: Rs. 200 government fee + Rs. 300 e-affidavit + Rs. 50 PITB charge, paid via e-Pay or challan.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000005', 'Can I get my Rawalpindi Domicile delivered at home via Maryam Ki Dastak?', 'Yes! Maryam Ki Dastak home delivery is available for an additional Rs. 900 to Rs. 1,200 service charge, and takes 2 to 3 days if Dastak fast track is available in your area.', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000005', 'Where do I get Form P, AC Verification Form, and the Rs. 300 affidavit?', 'All three — Form P, the AC Verification Form, and the Rs. 300 stamp paper e-affidavit — are available directly at e-Khidmat Markaz, District Complex, Rawalpindi.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000005', 'How many days does a standard Rawalpindi Domicile take?', 'Standard processing through e-Khidmat Markaz takes 16 working days from the date of submission.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1050000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000005', 'What documents count as valid proof of residence?', 'Property papers, a utility bill, rent agreement, or voter list entry — make sure the address matches your CNIC or residence proof, and bring a parent or spouse CNIC copy.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', 'Does NADRA issue birth certificates in Rawalpindi?', 'No! Do not go to NADRA first. Birth certificates are issued by your local Union Council, Municipal Committee, or Cantonment Board. Afterward, use that certificate to apply for a B-Form at NADRA.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', 'Is birth registration really free within 7 years?', 'Yes! Timely birth registration within 7 years is completely free (Rs. 0). Late registration after 7 years costs Rs. 200 to Rs. 1,000 for Pakistani citizens, foreign national child registration is Rs. 2,000, and a correction costs Rs. 500.', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000006', 'How long does it take to get the computerized birth certificate?', 'If your documents are complete, the Union Council Secretary enters the record in the system and issues the computerized birth certificate the same day or in 2 to 3 days.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000006', 'What is the official NADRA fee & validity for a Child Registration Certificate (B-Form / CRC) afterward?', 'Per nadra.gov.pk/feeStructure, a NADRA CRC / B-Form costs Rs. 50 Normal (7 days) or Rs. 500 Executive (1 day) — Urgent is not offered. CRCs expire at ages 3, 10, and 18 (under 3: no biometrics, photo if applying for passport; 3–10: Photo + IRIS; 10–18: Photo + Fingerprints + IRIS).', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1060000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000006', 'What time should I visit the Union Council office?', 'Visit between 9:00 AM and 12:00 PM on weekdays, as the Union Council Secretary is usually available in the morning.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000007', 'What is the difference between a Police Character Certificate (Rs. 500) and General Police Verification (Rs. 300)?', 'For foreign visas, immigration, and embassies, you specifically need a Police Character Certificate (Rs. 500) with QR code — NOT General Police Verification (Rs. 300).', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000007', 'Where are Police Khidmat Markaz centers located in Rawalpindi?', 'You can apply at any Police Khidmat Markaz in Punjab. In Rawalpindi district: Rescue 15 Office at Liaqat Bagh Metro Station (Murree Road), plus Taxila, Murree, Gujar Khan, and Kahuta centers.', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', 'How long does it take to receive the certificate?', 'Your counter visit takes 30 to 45 minutes (best window: 9:00 AM to 11:00 AM), and the original QR-coded certificate is delivered by courier in 3 working days.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000007', 'What if my CNIC address does not match my current address?', 'Update your address with NADRA first before applying — a mismatch between your CNIC address and current residence causes verification issues.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1070000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000007', 'Do embassies accept a photocopy of the Police Character Certificate?', 'No — embassies require the original certificate with its scannable QR verification code. Apply well ahead of your deadline so courier delivery arrives in time.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000008', 'What is the fee for a child e-Passport under 18?', 'A child’s e-passport uses the same fee table as adults: Rs. 9,000 Normal (21 working days) and Rs. 15,000 Urgent (5 working days) for 36 pages and 5-year validity.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000008', 'Can a child under 15 get a 10-year passport?', 'No. Children under 15 years of age are issued 5-year validity passports only.', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000008', 'Do both parents have to visit Regional Passport Office Rawalpindi?', 'Yes, both parents must be present with valid unexpired CNICs. If one parent cannot attend, you must bring an attested consent affidavit from the absent parent or the file will be rejected.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000008', 'What official NADRA B-Form / CRC biometric requirements apply by child age?', 'Under NADRA’s official CRC policy (nadra.gov.pk): under age 3 requires a photograph on the CRC if processing a passport; ages 3 to 10 require Photograph + IRIS (child present at NADRA); ages 10 to 17 MUST include Photograph, Fingerprints & IRIS. CRC fees at NADRA are Rs. 50 Normal (7 days) or Rs. 500 Executive (1 day).', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1080000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000008', 'How is the child’s passport delivered?', 'After biometrics, live photo capture at the office, and fee payment, the passport is delivered by courier (21 working days Normal, 5 working days Urgent).', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000009', 'Can I go straight to NADRA with my manual handwritten Nikahnama?', 'No! Under NADRA Regulation 41, you must bring a Computerized Marriage Registration Certificate (MRC) from your Union Council (or foreign authority) along with your spouse’s CNIC, POC, or Passport copy.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000009', 'What are the exact official NADRA fees & delivery days for post-marriage CNIC modification?', 'Per nadra.gov.pk/feeStructure: Ordinary CNIC modification is Rs. 400 Normal (15 days), Rs. 1,150 Urgent (12 days), or Rs. 2,150 Executive (6 days). Smart CNIC modification is Rs. 750 Normal (31 days), Rs. 1,500 Urgent (23 days), or Rs. 2,500 Executive (9 days). Database-only marital status update (no new printed card) is Rs. 100 at NRC (2 days) or USD 5 via PakID app (2 days).', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000009', 'Can a woman retain her father’s name on her CNIC after marriage instead of adopting her husband’s name?', 'Yes! Under official NADRA rules, a married woman has the legal choice to keep her father’s name on her CNIC while only updating her marital status to Married — or she can switch to her husband’s name/surname using her computerized MRC.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000009', 'Why should both husband and wife update their NADRA records (and how much is an FRC)?', 'Update marital status for both husband and wife so your Family Registration Certificate (FRC — Rs. 1,000 Executive, 1 day) matches accurately for visas and banking. Also think carefully before changing your given/surname, as NADRA restricts subsequent name changes.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1090000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000009', 'Can I apply online via PakID app instead of visiting Saddar Mega Center?', 'Yes! Once you have your Union Council Computerized MRC, you can apply via NADRA’s official PakID app (Google Play / App Store) or visit NADRA Mega Center, Saddar, Rawalpindi on a weekday morning. For questions, call NADRA’s 24/7 Helpline: 1777 or +92 51 111 786 100.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000010', 'How do I safely check my Punjab E-Challan without falling for scams?', 'Never click links sent in SMS messages — many are scams. Always open your browser and type echallan.psca.gop.pk yourself, then search with your vehicle registration number and owner 13-digit CNIC (without dashes) or chassis number.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000010', 'What are the common Punjab E-Challan fine amounts?', 'Common fines include: No helmet Rs. 2,000; Red light violation Rs. 2,000 to Rs. 5,000; No driving licence Rs. 5,000; and Overspeeding Rs. 2,000 to Rs. 10,000. Always check your exact fine on the portal.', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000010', 'How many days do I have to pay an e-Challan?', 'Pay within 10 days to avoid extra penalty. Remember that once you generate a 17-digit PSID in e-Pay Punjab, you must pay that PSID within 24 hours before it expires.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000010', 'Which payment methods work for the 17-digit PSID?', 'You can pay the 17-digit PSID through JazzCash, Easypaisa, your Pakistani bank app, a 1Link ATM, or over the counter at a bank branch. Always save a screenshot of your payment receipt.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1100000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000010', 'How long does payment confirmation take to appear on the portal?', 'Checking your challan takes 2 minutes, and payment confirmation takes 10 minutes to 2 hours to reflect on echallan.psca.gop.pk. Ignoring unpaid challans blocks vehicle transfer and driving licence renewal.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1110000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000011', 'Which are the best official NADRA centers for CNIC renewal in Islamabad?', 'Primary center: NADRA Mega Center, Blue Area (Khyber Plaza), Islamabad (98-West, Khyber Plaza, Jinnah Avenue, Blue Area, Islamabad (3 shifts, open Saturday). Other centers: RHO/PHQ G-10/4 (Plot 30, Mauve Area), Asaan Khidmat Center G-9/1, PFC F-6/1 & G-11/4, or PakID app. 24/7 Helpline: 1777.). Alternative official NADRA centers in Islamabad include: RHO/PHQ G-10/4 (Plot #30, Mauve Area), Asaan Khidmat Center G-9/1 (open Saturday), and Public Facilitation Centers in F-6/1 & G-11/4.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1110000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000011', 'What are the official NADRA CNIC renewal fees and delivery days in Islamabad?', 'NADRA fees are uniform nationwide (nadra.gov.pk/feeStructure): Smart CNIC (SNIC) is Rs. 750 Normal (31 days), Rs. 1,500 Urgent (23 days), and Rs. 2,500 Executive (9 days). Ordinary CNIC (Teslin) is Rs. 400 Normal (15 days), Rs. 1,150 Urgent (12 days), and Rs. 2,150 Executive (6 days).', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1110000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000011', 'Can I renew my CNIC online from Islamabad using the PakID app?', 'Yes! You can apply online via NADRA’s official PakID mobile app (Android & iOS) and have your card delivered or track status in-app. If biometric or live photo recapture is flagged, visit any nearby NADRA Registration Centre (NRC).', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1110000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000011', 'Do I need gazetted officer attestation for CNIC renewal?', 'No. Under Rule 12 of NADRA (NIC) Rules, 2002, no attestation is required for renewing a CNIC, and you can apply up to 1 month after expiry with just your original old CNIC (plus utility bill/MRC only if changing address or marital status).', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1110000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000011', 'How do I verify NADRA center shifts or report an issue in Islamabad?', 'Call NADRA’s 24/7 Helpline on 1777 (mobile) or +92 51 111 786 100 (landline/overseas), email csd@nadra.gov.pk, or check nadra.gov.pk before visiting.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1120000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000012', 'Which are the best official NADRA centers for CNIC renewal in Lahore?', 'Primary center: NADRA Mega Center, Egerton Road (Shimla Pahari), Lahore (9-Egerton Road, Near Shimla Pahari, Lahore (3 shifts, open Saturday). Other Mega Centers: Peco Road (Building 39, Block 10, Sector B-1, Quaid-e-Azam Town) & 15-A Sanda Road; plus DHA Phase 1/4 & RHO 73 Trade Centre Johar Town. 24/7 Helpline: 1777.). Alternative official NADRA centers in Lahore include: Mega Center Peco Road (Quaid-e-Azam Town), Mega Center 15-A Sanda Road, DHA Phase 1 & Phase 4 (2 shifts), and RHO Lahore (73 Trade Centre, Johar Town).', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
