INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1180000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000018', 'Where is the official FBR Regional Tax Office (RTO) in Rawalpindi?', 'Regional Tax Office (RTO) Rawalpindi & FBR IRIS Online: Online 24/7 via iris.fbr.gov.pk (free for Individuals), or walk in free to RTO Rawalpindi Facilitation Counter: 12-Mayo Road, Civil Lines (Near Katchery / Fatima Jinnah Women University), Rawalpindi. Tel: 051-9270405 / TFC: 051-9270408 | National Helpline: 051-111-772-772.', 1) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1180000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000018', 'How much does FBR NTN registration cost in Rawalpindi?', 'Rs. 0 — completely free! Both online registration via FBR IRIS (iris.fbr.gov.pk) and in-person assistance at Regional Tax Office (RTO) Rawalpindi & FBR IRIS Online carry zero government fee.', 2) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1180000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000018', 'Do individuals get a separate NTN number or is my CNIC my NTN?', 'For Pakistani individuals (salaried, freelancers, sole proprietors), your 13-digit CNIC (without dashes) IS your official NTN / FBR Registration Number. Download your Form 181 Registration Order under Completed Tasks in IRIS.', 3) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1180000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000018', 'When do I need to visit RTO Rawalpindi in person instead of using IRIS online?', 'Individual taxpayers can register 100% online on iris.fbr.gov.pk. Visit Regional Tax Office (RTO) Rawalpindi & FBR IRIS Online (Tel: 051-9270405) if you are registering an AOP (partnership) or Company, need free walk-in help with Form 181, or are locked out of your IRIS credentials.', 4) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
INSERT INTO public.faqs (id, process_id, question, answer, sort_order) VALUES ('f1180000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000018', 'What is the official FBR tax rate for IT freelancers and how do I reach FBR support?', 'Under Section 154A of the Income Tax Ordinance, IT and IT-enabled services export proceeds are subject to 1% final tax (0.25% if PSEB-registered; confirm current Finance Act provisions on fbr.gov.pk). Contact FBR National Helpline at 051-111-772-772 (Females: 051-9107025) or helpline@fbr.gov.pk.', 5) ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, answer = EXCLUDED.answer, sort_order = EXCLUDED.sort_order;
