INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21010000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'Regional Passport Office, Rawalpindi (GT Road)', 'Rawalpindi', '2026-11-16', 60, 4, 'Reached GT Road RPO at 8:45 AM — paid Rs. 9,000 via PSID beforehand and finished smoothly!', 'approved', '2026-11-16T10:15:00Z') ON CONFLICT (id) DO UPDATE SET office_name = EXCLUDED.office_name, city = EXCLUDED.city, visit_date = EXCLUDED.visit_date, wait_minutes = EXCLUDED.wait_minutes, rating = EXCLUDED.rating, tip = EXCLUDED.tip, status = EXCLUDED.status;
INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21010000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 'Regional Passport Office, Rawalpindi (GT Road)', 'Rawalpindi', '2026-11-15', 75, 4, 'Only e-passports are issued now — photo is taken live at the counter so no studio photo needed.', 'approved', '2026-11-15T11:30:00Z') ON CONFLICT (id) DO UPDATE SET office_name = EXCLUDED.office_name, city = EXCLUDED.city, visit_date = EXCLUDED.visit_date, wait_minutes = EXCLUDED.wait_minutes, rating = EXCLUDED.rating, tip = EXCLUDED.tip, status = EXCLUDED.status;
