INSERT INTO public.wait_times (id, process_id, office_name, city, visit_date, wait_minutes, rating, tip, status, created_at) VALUES ('21010000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000001', 'Regional Passport Office, Rawalpindi (GT Road)', 'Rawalpindi', '2026-11-13', 55, 4, 'Wednesday morning between 8:30 and 10:00 AM moves fast. Check your CNIC expiry before coming!', 'approved', '2026-11-13T09:50:00Z') ON CONFLICT (id) DO UPDATE SET office_name = EXCLUDED.office_name, city = EXCLUDED.city, visit_date = EXCLUDED.visit_date, wait_minutes = EXCLUDED.wait_minutes, rating = EXCLUDED.rating, tip = EXCLUDED.tip, status = EXCLUDED.status;
